INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2979703', 'Po Valley Raid', 'The Battle of Insubria in 203 BC was the culmination of a major war, carried out by the Carthaginian commander Mago, brother of Hannibal Barca, at the end of the Second Punic War between Rome and Carthage in what is now northwestern Italy. Mago had landed at Genoa, Liguria, two years before, in an effort to keep the Romans busy to the North and thus hamper indirectly their plans to invade Carthage''s hinterland in Africa (modern Tunisia).', -203, NULL, NULL, NULL, NULL, NULL, 'year', '203 BCE', 50, 'https://en.wikipedia.org/wiki/Battle_of_Insubria'),
  ('Q664365', 'Battle of Octodurus', 'The battle of Octodurus took place in the winter of 57–56 BC in the Gallic town of Octodurus in what is now Martigny, Valais, Switzerland. The battle resulted from a Roman attempt to open the Great St.', -57, NULL, NULL, -56, NULL, NULL, 'year', '57 BCE – 56 BCE', 50, 'https://en.wikipedia.org/wiki/Battle_of_Octodurus'),
  ('Q1512205', 'Battle of Vindonissa', 'The Battle of Vindonissa was fought in 298 or 302 between the Imperial Roman army, led by Emperor Constantius Chlorus, and the Alemanni. The Romans won the battle, fought in Vindonissa, strengthening Rome''s defenses along the Rhine.', 298, NULL, NULL, NULL, NULL, NULL, 'year', '298', 45, 'https://en.wikipedia.org/wiki/Battle_of_Vindonissa'),
  ('Q326989', 'Battle of Morgarten', 'The Battle of Morgarten took place on 15 November 1315, when troops of Schwyz, supported by their allies of Uri and Unterwalden, ambushed an Austrian army under the command of Leopold I, Duke of Austria on the shores of Lake Ägeri, in the territory of Schwyz. After a brief close-quarters battle, the Austrian army was routed, with numerous slain or drowned.', 1315, 11, 15, NULL, NULL, NULL, 'day', '15 November 1315', 63, 'https://en.wikipedia.org/wiki/Battle_of_Morgarten'),
  ('Q667606', 'Battle of Laupen', 'The Battle of Laupen was fought in June 1339, between Bern and its allies on one side, and Freiburg together with feudal landholders from the County of Burgundy and Habsburg territories on the other. Bern was victorious, consolidating its position in the region.', 1339, 6, 21, NULL, NULL, NULL, 'day', '21 June 1339', 51, 'https://en.wikipedia.org/wiki/Battle_of_Laupen'),
  ('Q810406', 'Basel massacre', 'The Basel Massacre was an anti-Semitic massacre in Basel, which occurred in 1349 in connection with alleged well poisoning as part of the Black Death persecutions, carried out against the Jews in Europe at the time of the Black Death. A number of Jews, variously given as between 300 and 600 (according to contemporary Medieval chronicles) or 50 to 70 (according to some modern historians) were burned alive, after being locked in a wooden structure built on a nearby island in the Rhine.', 1349, 1, 16, NULL, NULL, NULL, 'day', '16 January 1349', 47, 'https://en.wikipedia.org/wiki/Basel_Massacre'),
  ('Q672705', '1356 Basel earthquake', 'The 1356 Basel earthquake is the most significant seismological event to have occurred in Central Europe in recorded history and had a moment magnitude in the range of 6.0–7.1. This earthquake, which occurred on 18 October 1356, is also known as the Sankt-Lukas-Tag Erdbeben (English: Saint Luke''s Day Earthquake), as 18 October is the feast day of Saint Luke the Evangelist.', 1356, 10, 18, NULL, NULL, NULL, 'day', '18 October 1356', 57, 'https://en.wikipedia.org/wiki/1356_Basel_earthquake'),
  ('Q661759', 'Battle of Sempach', 'The Battle of Sempach was fought on 9 July 1386, between Leopold III, Duke of Austria and the Old Swiss Confederacy. The battle was a decisive Swiss victory in which Duke Leopold and numerous Austrian nobles died.', 1386, 7, 9, NULL, NULL, NULL, 'day', '9 July 1386', 57, 'https://en.wikipedia.org/wiki/Battle_of_Sempach'),
  ('Q667460', 'Battle of Näfels', 'The Battle of Näfels was fought on 9 April 1388 between the Swiss canton of Glarus, supported by its allies of the Old Swiss Confederation, and the Duchy of Austria ruled by the House of Habsburg. It was a decisive victory for Glarus and led to its independence from Habsburg rule.', 1388, 4, 9, NULL, NULL, NULL, 'day', '9 April 1388', 51, 'https://en.wikipedia.org/wiki/Battle_of_N%C3%A4fels'),
  ('Q673411', 'Battle of Arbedo', 'The Battle of Arbedo was fought on 30 June 1422 between the Duchy of Milan and the Swiss Confederation, and ended with a Milanese victory. In 1419, the Swiss cantons of Uri and Unterwalden bought the fortified town of Bellinzona from the House of Sax but were unable to defend it adequately.', 1422, 6, 30, NULL, NULL, NULL, 'day', '30 June 1422', 51, 'https://en.wikipedia.org/wiki/Battle_of_Arbedo'),
  ('Q451404', 'Battle of St. Jakob an der Sihl', 'The Battle of St. Jakob an der Sihl was a battle of the Old Zürich War that occurred on 22 July 1443, resulting in a defeat for Zürich.', 1443, 7, 22, NULL, NULL, NULL, 'day', '22 July 1443', 43, 'https://en.wikipedia.org/wiki/Battle_of_St._Jakob_an_der_Sihl'),
  ('Q451853', 'Battle of St. Jakob an der Birs', 'The Battle of St. Jakob an der Birs was fought between the Old Swiss Confederacy and French (mostly Armagnac) mercenaries, on the banks of the river Birs.', 1444, 8, 26, NULL, NULL, NULL, 'day', '26 August 1444', 47, 'https://en.wikipedia.org/wiki/Battle_of_St._Jakob_an_der_Birs'),
  ('Q319592', 'Battle on the Planta', 'The Battle on the Planta, fought on 13 November 1475 around Conthey near Sion, Valais, Switzerland, was part of the Burgundian Wars.', 1475, 11, 13, NULL, NULL, NULL, 'day', '13 November 1475', 47, 'https://en.wikipedia.org/wiki/Battle_on_the_Planta'),
  ('Q688502', 'Battle of Morat', 'The Battle of Morat ((French: Bataille de Morat; German: Schlacht bei Murten) took place during the Burgundian Wars (1474–1477) that was fought on 22 June 1476 between Charles the Bold, the Duke of Burgundy, and a Swiss Confederation army at Morat (Murten), about 30 kilometres from Bern. It was the second major engagement of the Burgundian Wars, and ended in a crippling defeat for Charles the Bold.', 1476, 6, 22, NULL, NULL, NULL, 'day', '22 June 1476', 57, 'https://en.wikipedia.org/wiki/Battle_of_Morat'),
  ('Q472614', 'Battle of Giornico', 'In the Battle of Giornico, also known as the battle of large rocks (Italian: Battaglia di Giornico, dei Sassi Grossi; German: Schlacht bei Giornico) (28 December 1478), about 600 Swiss troops ambushed from above and defeated a larger force of the Duchy of Milan, confined in a narrow icy valley, by rolling large boulders down the hillside against the Milanese.', 1478, 12, 28, NULL, NULL, NULL, 'day', '28 December 1478', 43, 'https://en.wikipedia.org/wiki/Battle_of_Giornico'),
  ('Q165136', 'Swabian War', 'The Swabian War of 1499 (Alemannic German: Schwoobechrieg; spelling depending on dialect), called Schwabenkrieg or Schweizerkrieg ("Swiss War") in Germany and Engadiner Krieg ("War of the Engadin") in Austria, was the last major armed conflict between the Old Swiss Confederacy and the House of Habsburg. What had begun as a local conflict over the control of the Val Müstair and the Umbrail Pass in the Grisons soon got out of hand when both parties called upon their allies for help; the Habsburgs demanding the support of the Swabian League, while the Federation of the Three Leagues of the…', 1499, 9, NULL, 1499, 9, 22, 'month', 'September 1499 – 22 September 1499', 66, 'https://en.wikipedia.org/wiki/Swabian_War'),
  ('Q251597', 'Battle of Dornach', 'The Battle of Dornach was fought on 22 July 1499 between the troops of Emperor Maximilian I and the Old Swiss Confederacy, close to the Swiss village of Dornach. The battle ended in a decisive defeat for Maximilian, and concluded the Swabian War between the Swiss and the Swabian League.', 1499, 7, 22, NULL, NULL, NULL, 'day', '22 July 1499', 53, 'https://en.wikipedia.org/wiki/Battle_of_Dornach'),
  ('Q685164', 'Treaty of Basel', 'The Treaty of Basel of 22 September 1499 was an armistice following the Battle of Dornach, concluding the Swabian War, fought between the Swabian League and the Old Swiss Confederacy. Though the war had concluded in multiple Swiss victories, both Switzerland and the Swabian League were exhausted, and the leaders of both sides desired peace.', 1499, 9, 22, NULL, NULL, NULL, 'day', '22 September 1499', 57, 'https://en.wikipedia.org/wiki/Treaty_of_Basel_(1499)'),
  ('Q233594', 'Second War of Kappel', 'The Second War of Kappel (German: Zweiter Kappelerkrieg) was an armed conflict in 1531 between the Catholic and the Protestant cantons of the Old Swiss Confederacy during the Reformation in Switzerland.', 1531, 10, 11, NULL, NULL, NULL, 'day', '11 October 1531', 56, 'https://en.wikipedia.org/wiki/Second_War_of_Kappel'),
  ('Q331518', 'Battle of Rheinfelden', 'The Battle of Rheinfelden (28 February and 3 March 1638) was a military event in the course of the Thirty Years'' War, consisting in fact of two battles to the north and south of the present-day town of Rheinfelden. On one side was a French-allied mercenary army led by Bernhard of Saxe-Weimar while the other side consisted of a joint Bavarian and Holy Roman Empire army and led by Johann von Werth and Federico Savelli.', 1638, 2, 28, 1638, 3, 2, 'day', '28 February 1638 – 2 March 1638', 47, 'https://en.wikipedia.org/wiki/Battle_of_Rheinfelden'),
  ('Q3403838', 'Capture of Porrentruy', 'The capture of Porrentruy was a siege of the Swiss town of Porrentruy. The town was held by Austria and attacked by the French.', 1792, 4, 28, NULL, NULL, NULL, 'day', '28 April 1792', 41, 'https://en.wikipedia.org/wiki/Capture_of_Porrentruy'),
  ('Q667080', 'Peace of Basel', 'The Peace of Basel of 1795 consists of three peace treaties involving France during the French Revolution (represented by François de Barthélemy). The first was with Prussia (represented by Karl August von Hardenberg) on 5 April; The second was with Spain (represented by Domingo d''Yriarte) on 22 July, ending the War of the Pyrenees; and The third was with the Landgraviate of Hesse-Kassel (represented by Friedrich Sigismund Waitz von Eschen) on 28 August, concluding the stage of the French Revolutionary Wars against the First Coalition.', 1795, 4, 5, NULL, NULL, NULL, 'day', '5 April 1795', 66, 'https://en.wikipedia.org/wiki/Peace_of_Basel'),
  ('Q26749', 'War of the Second Coalition', 'The War of the Second Coalition (French: Guerre de la Deuxième Coalition) (1798–1802) was the second war between revolutionary France and a coalition of European monarchies, led by Britain, Austria and Russia, and including the Ottoman Empire, Portugal, Naples and various German monarchies. Prussia did not join the coalition, while Spain supported France.', 1798, 6, 28, 1802, 3, 25, 'day', '28 June 1798 – 25 March 1802', 73, 'https://en.wikipedia.org/wiki/War_of_the_Second_Coalition'),
  ('Q281461', 'Battle of Grauholz', 'The Battle of Grauholz on 5 March 1798 was a battle between a Bernese army under Karl Ludwig von Erlach against the French Revolutionary Army under Balthazar Alexis Henri Schauenburg. The battle took place at Grauholz, a wooded hill in what is now the municipalities of Urtenen-Schönbühl and Moosseedorf in the canton of Bern in Switzerland.', 1798, 3, 5, NULL, NULL, NULL, 'day', '5 March 1798', 47, 'https://en.wikipedia.org/wiki/Battle_of_Grauholz'),
  ('Q233426', 'Second Battle of Zurich', 'The Second Battle of Zurich (25–26 September 1799) was a key victory by the Republican French army in Switzerland led by André Masséna over a Russian force commanded by Alexander Rimsky-Korsakov near Zürich, as it broke the stalemate that had resulted from the First Battle of Zurich three months earlier and led to the withdrawal of Russia from the Second Coalition. Masséna took full advantage of the incompetence of the Russian commander who had accidentally scattered his forces, and launched a bold assault.', 1799, 9, 25, 1799, 9, 26, 'day', '25 September 1799 – 26 September 1799', 52, 'https://en.wikipedia.org/wiki/Second_Battle_of_Zurich'),
  ('Q575973', 'First Battle of Zurich', 'The First Battle of Zurich, from 4 to 7 June 1799, forced French General André Masséna to yield the city of Zurich to the Austrians, under Archduke Charles, and to retreat beyond the Limmat, where he managed to fortify his positions, which resulted in a stalemate. The first battle of Zurich saw Austrian attacks on strong French positions, which were captured but then had to be abandoned due to a French counterattack.', 1799, 6, 7, 1799, 6, 5, 'day', '7 June 1799 – 5 June 1799', 51, 'https://en.wikipedia.org/wiki/First_Battle_of_Zurich'),
  ('Q685798', 'Battle of Winterthur', 'The Battle of Winterthur (27 May 1799) was an important action between elements of the Army of the Danube and elements of the Habsburg army, commanded by Friedrich Freiherr von Hotze, during the War of the Second Coalition, part of the French Revolutionary Wars. The small town of Winterthur lies 18 kilometers (11 mi) northeast of Zürich, in Switzerland.', 1799, 5, 27, NULL, NULL, NULL, 'day', '27 May 1799', 56, 'https://en.wikipedia.org/wiki/Battle_of_Winterthur'),
  ('Q1152249', 'Second Italian Campaign', 'The Marengo campaign (4 April – 15 June 1800) saw a Habsburg Austrian army led by General der Kavallerie Michael von Melas fight against the defending French Army of Italy under General of Division (GD) André Massena and the invading French Reserve Army commanded by First Consul Napoleon Bonaparte. In early April, Melas launched a successful offensive that split the outnumbered Army of Italy and initiated the Siege of Genoa with Massena''s forces trapped within the city.', 1800, NULL, NULL, NULL, NULL, NULL, 'year', '1800', 45, 'https://en.wikipedia.org/wiki/Marengo_campaign'),
  ('Q248743', 'Züriputsch', 'The Züriputsch of 6 September 1839 was a putsch of the rural conservative population against the liberal rule of the city of Zurich on the eve of the formation of the Swiss federal state. The reason for the putsch was the appointment of the controversial German theologian David Strauss to the theological faculty of the University of Zurich by the liberal government.', 1839, 9, 6, NULL, NULL, NULL, 'day', '6 September 1839', 43, 'https://en.wikipedia.org/wiki/Z%C3%BCriputsch'),
  ('Q688297', 'Sonderbund War', 'The Sonderbund War (German: Sonderbundskrieg, French: Guerre du Sonderbund, Italian: Guerra del Sonderbund) of November 1847 was a civil war in Switzerland, then still a relatively loose confederacy of cantons. It ensued after seven Catholic cantons formed the Sonderbund ("separate alliance") in 1845 to protect their interests against a centralization of power.', 1847, 11, 3, 1847, 11, 29, 'day', '3 November 1847 – 29 November 1847', 65, 'https://en.wikipedia.org/wiki/Sonderbund_War'),
  ('Q672743', 'Treaty of Zürich', 'The Treaty of Zurich was signed by the Austrian Empire, the French Empire, and the Kingdom of Sardinia on 10 November 1859. The agreement was a reaffirmation of the terms of the preliminary peace of Villafranca, which brought the Austro-Sardinian War to an official close.', 1859, 11, 10, NULL, NULL, NULL, 'day', '10 November 1859', 55, 'https://en.wikipedia.org/wiki/Treaty_of_Z%C3%BCrich'),
  ('Q610272', 'Geneva Convention of 1864', 'The Geneva Convention (I) for the Amelioration of the Condition of the Wounded in Armies in the Field (French: Convention pour l''amélioration du sort des blessés et des malades dans les forces armées en campagne), more commonly referred to as the First Geneva Convention or Geneva Convention I and abbreviated as GCI, is the first of the four treaties of the 1949 Geneva Conventions. It defines "the basis on which rest the rules of international law for the protection of the victims of armed conflicts." GCI is the fourth iteration of a series of Geneva Conventions, all of which sought to…', 1864, 8, 22, NULL, NULL, NULL, 'day', '22 August 1864', 71, 'https://en.wikipedia.org/wiki/First_Geneva_Convention'),
  ('Q2629126', 'Treaty of Bern', 'The Treaty of Bern (formally the Treaty concerning the formation of a General Postal Union), signed on 9 October 1874, established the General Postal Union, which is today known as the Universal Postal Union. Named for the Swiss city of Bern, where it was signed, the treaty was the result of an international conference convened by the Swiss Government on 15 September 1874.', 1874, 10, 9, NULL, NULL, NULL, 'day', '9 October 1874', 53, 'https://en.wikipedia.org/wiki/Treaty_of_Bern'),
  ('Q217398', 'Berne Convention for the Protection of Literary and Artistic Works', 'The Berne Convention for the Protection of Literary and Artistic Works, usually known as the Berne Convention, was an international assembly held in 1886 in the Swiss city of Bern by ten European countries with the goal of agreeing on a set of legal principles for the protection of original work and intellectual property. They drafted and adopted a multi-party contract containing agreements for a uniform, border-crossing system that became known under the same name.', 1886, 9, 9, NULL, NULL, NULL, 'day', '9 September 1886', 78, 'https://en.wikipedia.org/wiki/Berne_Convention'),
  ('Q193258', 'Treaty of Lausanne', 'The Treaty of Lausanne (French: Traité de Lausanne; Turkish: Lozan Antlaşması) is a peace treaty negotiated during the Lausanne Conference of 1922–1923 and signed in the Palais de Rumine in Lausanne, Switzerland, on 24 July 1923. The treaty officially resolved the conflict that had initially arisen between the Ottoman Empire and the Allied French Republic, British Empire, Kingdom of Italy, Empire of Japan, Kingdom of Greece, Kingdom of Yugoslavia, and the Kingdom of Romania since the outset of World War I. The original text of the treaty is in English and French.', 1923, 7, 24, NULL, NULL, NULL, 'day', '24 July 1923', 81, 'https://en.wikipedia.org/wiki/Treaty_of_Lausanne'),
  ('Q152925', 'Locarno Treaties', 'The Locarno Treaties, known collectively as the Locarno Pact, were seven post–World War I agreements negotiated amongst Germany, France, the United Kingdom, Belgium, Italy, Poland and Czechoslovakia in late 1925. In the main treaty, the five western European nations pledged to guarantee the inviolability of the German-French and German-Belgian borders as defined in the Treaty of Versailles.', 1925, 10, 16, NULL, NULL, NULL, 'day', '16 October 1925', 73, 'https://en.wikipedia.org/wiki/Locarno_Treaties'),
  ('Q605626', 'Geneva Protocol', 'The Protocol for the Prohibition of the Use in War of Asphyxiating, Poisonous or other Gases, and of Bacteriological Methods of Warfare, usually called the Geneva Protocol, is a treaty prohibiting the use of chemical and biological weapons in international armed conflicts. It was signed at Geneva on 17 June 1925 and entered into force on 8 February 1928.', 1925, 6, 17, NULL, NULL, NULL, 'day', '17 June 1925', 63, 'https://en.wikipedia.org/wiki/Geneva_Protocol'),
  ('Q589276', 'Slavery Convention', 'The 1926 Slavery Convention or the Convention to Suppress the Slave Trade and Slavery is an international treaty created under the auspices of the League of Nations and first signed on 25 September 1926. It was registered in League of Nations Treaty Series on 9 March 1927, the same day it went into effect.', 1926, NULL, NULL, NULL, NULL, NULL, 'year', '1926', 62, 'https://en.wikipedia.org/wiki/1926_Slavery_Convention'),
  ('Q2594768', 'Geneva Convention on Prisoners of War', 'The Geneva Convention on Prisoners of War was signed at Geneva on 27 July 1929. Its official name is the Convention relative to the Treatment of Prisoners of War.', 1929, 7, 27, NULL, NULL, NULL, 'day', '27 July 1929', 52, 'https://en.wikipedia.org/wiki/Geneva_Convention_on_Prisoners_of_War'),
  ('Q679793', 'Lausanne Conference of 1932', 'The Lausanne Conference of 1932, held from 16 June to 9 July 1932 in Lausanne, Switzerland, was a meeting of representatives from the United Kingdom, France, Italy, Belgium, Japan and Germany that resulted in an agreement to lower Germany''s World War I reparations obligations as imposed by the Treaty of Versailles and the 1929 Young Plan. The reduction of approximately 90 per cent was made as a result of the difficult economic circumstances during the Great Depression.', 1932, NULL, NULL, NULL, NULL, NULL, 'year', '1932', 48, 'https://en.wikipedia.org/wiki/1932_Lausanne_Conference'),
  ('Q167759', 'Baltic Entente', 'The Baltic Entente was based on Treaty of Good-Understanding and Co-operation signed between Lithuania, Latvia, and Estonia on 12 September 1934 in Geneva. The main objective of the agreement was joint action in foreign policy.', 1934, 9, 12, NULL, NULL, NULL, 'day', '12 September 1934', 65, 'https://en.wikipedia.org/wiki/Baltic_Entente'),
  ('Q194284', 'General Agreement on Tariffs and Trade', 'The General Agreement on Tariffs and Trade (GATT) is a legal agreement between many countries, whose overall purpose was to promote international trade by reducing or eliminating trade barriers such as tariffs or quotas. According to its preamble, its purpose was the "substantial reduction of tariffs and other trade barriers and the elimination of preferences, on a reciprocal and mutually advantageous basis".', 1947, 10, 30, NULL, NULL, NULL, 'day', '30 October 1947', 77, 'https://en.wikipedia.org/wiki/General_Agreement_on_Tariffs_and_Trade'),
  ('Q583921', 'Second Geneva Convention', 'The Geneva Convention (II) for the Amelioration of the Condition of Wounded, Sick and Shipwrecked Members of Armed Forces at Sea (French: Convention pour l''amélioration du sort des blessés, des malades et des naufragés des forces armées sur mer), more commonly referred to as the Second Geneva Convention or Geneva Convention II and abbreviated as GCII, is one of the four treaties of the 1949 Geneva Conventions. It was first adopted in 1949, replacing the Hague Convention (X) of 1907.', 1949, 8, 12, NULL, NULL, NULL, 'day', '12 August 1949', 67, 'https://en.wikipedia.org/wiki/Second_Geneva_Convention'),
  ('Q19044383', 'Geneva Convention on Road Traffic', 'The Geneva Convention on Road Traffic is an international treaty promoting the development and safety of international road traffic by establishing certain uniform rules among the contracting parties. The convention addresses minimum mechanical and safety equipment needed to be on board and defines an identification mark to identify the origin of the vehicle.', 1949, 9, 19, NULL, NULL, NULL, 'day', '19 September 1949', 45, 'https://en.wikipedia.org/wiki/Geneva_Convention_on_Road_Traffic'),
  ('Q369989', 'Universal Copyright Convention', 'Universal Copyright Convention (UCC) is an international instrument which was drawn up in 1952 under the auspices of UNESCO. The UCC was adopted in Geneva, Switzerland, in 1952, and enforced in 1955. It is one of the two principal international conventions protecting copyright; the other is the Berne Convention.', 1952, NULL, NULL, NULL, NULL, NULL, 'year', '1952', 63, 'https://en.wikipedia.org/wiki/Universal_Copyright_Convention'),
  ('Q482407', 'Geneva Conference', 'The Geneva Conference was intended to settle outstanding issues resulting from the Korean War and the First Indochina War and involved several nations. It took place in Geneva, Switzerland, from 26 April to 21 July 1954.', 1954, NULL, NULL, 1954, 7, 20, 'year', '1954', 73, 'https://en.wikipedia.org/wiki/1954_Geneva_Conference'),
  ('Q7888320', 'United Nations 1956 Supplementary Convention on the Abolition of Slavery', 'The Supplementary Convention on the Abolition of Slavery, the full title of which is the Supplementary Convention on the Abolition of Slavery, the Slave Trade, and Institutions and Practices Similar to Slavery, is a 1956 United Nations treaty which builds upon the 1926 Slavery Convention, which is still operative and which proposed to secure the abolition of slavery and of the slave trade, and the Forced Labour Convention of 1930, which banned forced or compulsory labour, by banning debt bondage, serfdom, child marriage, servile marriage, and child servitude.', 1956, 9, 7, NULL, NULL, NULL, 'day', '7 September 1956', 48, 'https://en.wikipedia.org/wiki/Supplementary_Convention_on_the_Abolition_of_Slavery'),
  ('Q173973', 'Swissair Flight 306', 'Swissair Flight 306, a Sud Aviation Caravelle named Schaffhausen, was a scheduled international flight from Zurich to Rome, via Geneva. It crashed near Dürrenäsch, Aargau, on 4 September 1963, shortly after take-off, killing all 80 people on board.', 1963, 9, 4, NULL, NULL, NULL, 'day', '4 September 1963', 51, 'https://en.wikipedia.org/wiki/Swissair_Flight_306'),
  ('Q673726', 'Swissair Flight 330', 'Swissair Flight 330 (SR330/SWR330) was a regularly scheduled passenger flight from Kloten, Switzerland, to Hong Kong (then a British colony) with an intermediate stopover in Tel Aviv, Israel. On 21 February 1970, a bomb exploded soon after takeoff, causing the plane to crash, killing all 47 passengers and crew.', 1970, 2, 21, NULL, NULL, NULL, 'day', '21 February 1970', 51, 'https://en.wikipedia.org/wiki/Swissair_Flight_330'),
  ('Q957806', 'Genuuva Accords', 'The Geneva Accords were the agreements on the settlement of the situation relating to Afghanistan, were signed on 14 April 1988 at the Geneva headquarters of the United Nations, between Afghanistan and Pakistan, with the United States and the Soviet Union serving as guarantors. The accords consisted of several instruments: a bilateral agreement between the Islamic Republic of Pakistan and the Republic of Afghanistan on the principles of mutual relations, in particular on non-interference and non-intervention; a declaration on international guarantees, signed by the Soviet Union and the…', 1988, 4, 14, NULL, NULL, NULL, 'day', '14 April 1988', 52, 'https://en.wikipedia.org/wiki/Geneva_Accords_(1988)'),
  ('Q2647284', 'Alitalia Flight 404', 'Alitalia Flight 404 (AZ404/AZA404) was an international passenger flight scheduled to fly from Linate Airport in Milan, Italy, to Zurich Airport in Zurich, Switzerland, which crashed on 14 November 1990. The McDonnell Douglas DC-9-32, operated by Alitalia, crashed into the woodlands of Weiach as it approached Zurich Airport, killing all 46 occupants on board.', 1990, 11, 14, NULL, NULL, NULL, 'day', '14 November 1990', 53, 'https://en.wikipedia.org/wiki/Alitalia_Flight_404'),
  ('Q741547', 'World Intellectual Property Organization Copyright Treaty', 'The World Intellectual Property Organization Copyright Treaty (WIPO Copyright Treaty or WCT) is an international treaty on copyright law adopted by the member states of the World Intellectual Property Organization (WIPO) in 1996. It provides additional protections for copyright to respond to advances in information technology since the formation of previous copyright treaties before it.', 1996, 12, NULL, NULL, NULL, NULL, 'month', 'December 1996', 57, 'https://en.wikipedia.org/wiki/WIPO_Copyright_Treaty'),
  ('Q2511409', 'WIPO Performances and Phonograms Treaty', 'The WIPO Performances and Phonograms Treaty (or WPPT) is an international treaty adopted in Geneva on 20 December 1996. It came into effect on 20 May 2002.', 1996, 12, 20, NULL, NULL, NULL, 'day', '20 December 1996', 48, 'https://en.wikipedia.org/wiki/WIPO_Performances_and_Phonograms_Treaty'),
  ('Q689359', 'Crossair Flight 498', 'Crossair Flight 498 was a scheduled commuter flight from Zurich, Switzerland, to Dresden, Germany. On 10 January 2000, the Saab 340B operating the flight crashed two minutes after takeoff in the Swiss municipality of Niederhasli, killing all 10 passengers and crew.', 2000, 1, 10, NULL, NULL, NULL, 'day', '10 January 2000', 56, 'https://en.wikipedia.org/wiki/Crossair_Flight_498'),
  ('Q569392', 'Crossair Flight 3597', 'Crossair Flight 3597 was a scheduled flight from Berlin Tegel Airport, Germany, to Zurich Airport, Switzerland. On 24 November 2001, the Avro RJ100 operating the route, registered as HB-IXM, crashed into a wooded range of hills near Bassersdorf and caught fire as a controlled flight into terrain.', 2001, 11, 24, NULL, NULL, NULL, 'day', '24 November 2001', 59, 'https://en.wikipedia.org/wiki/Crossair_Flight_3597'),
  ('Q13415210', '2013 European floods', 'Extreme flooding in Central Europe began after several days of heavy rain in late May and early June 2013. Flooding and damages primarily affected south and east German states (Thuringia, Saxony, Saxony-Anhalt, Lower Saxony, Bavaria and Baden-Württemberg), western regions of the Czech Republic (Bohemia), and Austria.', 2013, 5, 28, 2013, 6, 5, 'day', '28 May 2013 – 5 June 2013', 53, 'https://en.wikipedia.org/wiki/2013_European_floods'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q107529288', '2021 European floods', 'In July 2021, several European countries were affected by severe floods. Some were catastrophic, causing deaths and widespread damage.', 2021, NULL, NULL, 2021, 7, 25, 'year', '2021', 73, 'https://en.wikipedia.org/wiki/2021_European_floods'),
  ('Q137652531', '2026 Crans-Montana bar fire', 'On 1 January 2026 at 01:26 (CET), during New Year celebrations, a fire broke out at Le Constellation bar in the ski-resort town of Crans-Montana, Valais, Switzerland. Forty-one people died in the fire, and 115 others were injured, with 83 initially being treated for severe burns.', 2026, 1, 1, NULL, NULL, NULL, 'day', '1 January 2026', 72, 'https://en.wikipedia.org/wiki/2026_Crans-Montana_bar_fire');
